/**
 * Row-level duplicate used by the ops console's "duplicate project" action.
 * Copies the project exactly as it is — status, dates, archive state — under
 * the new name, slug and key; the console renumbers nothing.
 */
export async function duplicateProject(
  orgId: OrgId,
  projectId: ProjectId,
  name: string,
  slug: string,
  key: string,
): Promise<Project> {
  const source = getDb()
    .select()
    .from(projects)
    .where(and(orgPredicate(projects.orgId, orgId), eq(projects.id, projectId)))
    .get();
  if (!source) throw new Error(`Project ${projectId} not found`);

  const stamp = toIsoTimestamp(new Date());
  const row = getDb()
    .insert(projects)
    .values({
      ...source,
      id: newId(),
      name,
      slug,
      key,
      createdAt: stamp,
      updatedAt: stamp,
    })
    .returning()
    .get();

  return toProject(row);
}

/** Includes archived slugs — a restored project must not collide. */
export async function listTakenProjectSlugs(
  orgId: OrgId,
): Promise<readonly string[]> {
  const rows = getDb()
    .select({ slug: projects.slug })
    .from(projects)
    .where(orgPredicate(projects.orgId, orgId))
    .all();
  return rows.map((row) => row.slug);
}

/** Open/closed/overdue counters plus the last write, for the project card. */
export async function getProjectStats(
  orgId: OrgId,
  projectId: ProjectId,
  issueId: IssueId,
): Promise<Issue> {
  const row = getDb()
    .update(issues)
    .set(restorePatch())
    .where(and(orgPredicate(issues.orgId, orgId), eq(issues.id, issueId)))
    .returning()
    .get();

  if (!row) throw new Error(`Issue ${issueId} not found`);
  return toIssue(row);
}

/**
 * Copies a project's issues into another project, row for row, for the ops
 * console's "duplicate project" action: status, assignee and number come
 * along so the duplicate's board matches the original. Labels are copied too.
 */
export async function copyIssuesToProject(
  orgId: OrgId,
  fromProjectId: ProjectId,
  toProjectId: ProjectId,
): Promise<number> {
  const db = getDb();
  const page = await listIssues({
    orgId,
    projectId: fromProjectId,
    limit: 100,
    cursor: null,
  });

  const stamp = toIsoTimestamp(new Date());
  for (const issue of page.items) {
    const id = newId();
    db.insert(issues)
      .values({
        id,
        orgId,
        projectId: toProjectId,
        number: issue.number,
        title: issue.title,
        description: issue.description,
        status: issue.status,
        priority: issue.priority,
        authorId: issue.authorId,
        assigneeId: issue.assigneeId,
        parentId: null,
        estimate: issue.estimate,
        dueAt: issue.dueAt,
        startedAt: issue.startedAt,
        completedAt: issue.completedAt,
        createdAt: stamp,
        updatedAt: stamp,
      })
      .run();

    if (issue.labelIds.length > 0) {
      db.insert(issueLabels)
        .values(
          issue.labelIds.map((labelId) => ({ orgId, issueId: id, labelId })),
        )
        .run();
    }
  }

  return page.items.length;
}

/** Cascade behind `ProjectService.archiveProject`; returns the row count. */
export async function archiveIssuesForProject(
  orgId: OrgId,
  projectId: ProjectId,
): Promise<number> {
  const rows = getDb()
    .update(issues)
    .set(archivePatch())
    .where(
      and(
        ...compact(
          orgPredicate(issues.orgId, orgId),
          eq(issues.projectId, projectId),
          livePredicate(issues.archivedAt, {}),
        ),
      ),
    )
    .returning({ id: issues.id })
    .all();

  return rows.length;
}

import type {
  CommentId,
  IssueId,
  MemberId,
  OrgId,
  ProjectId,
  UserId,
  IsoTimestamp,
} from "./common";
import type { IssueStatus, IssuePriority } from "./issue";
import type { Role } from "./member";
import type { PlanId, LimitedResource } from "./billing";
import type { FeatureFlagKey } from "./feature-flag";

/** Fields present on every event payload; the bus stamps them on `emit`. */
export interface EventEnvelope {
  readonly orgId: OrgId;
  readonly actorId: UserId | null;
  readonly occurredAt: IsoTimestamp;
}

/**
 * The complete catalogue of domain events. `emit()` and `subscribe()` in
 * `src/lib/event-bus.ts` are keyed on this map, so adding an event here is the
 * only way to introduce one — services, jobs and the webhook dispatcher all
 * derive their handler signatures from it.
 */
export interface TaskflowEventMap {
  "project.created": EventEnvelope & {
    projectId: ProjectId;
    name: string;
    slug: string;
  };
  "project.archived": EventEnvelope & {
    projectId: ProjectId;
    issuesArchived: number;
  };
  "project.restored": EventEnvelope & { projectId: ProjectId };
  "issue.created": EventEnvelope & {
    issueId: IssueId;
    projectId: ProjectId;
    title: string;
    assigneeId: UserId | null;
    priority: IssuePriority;
  };
  "issue.updated": EventEnvelope & {
    issueId: IssueId;
    projectId: ProjectId;
    changedFields: readonly string[];
  };
  "issue.status_changed": EventEnvelope & {
    issueId: IssueId;
    projectId: ProjectId;
    from: IssueStatus;
    to: IssueStatus;
  };
  "issue.assigned": EventEnvelope & {
    issueId: IssueId;
    projectId: ProjectId;
    previousAssigneeId: UserId | null;

