/**
 * Clones a project (ADR 0012): gated like a creation, all or nothing, and
 * announced by a single `project.cloned`. Copies of the source's live issues
 * keep their content but start over — default status, unassigned, authored by
 * the person cloning, numbered from 1 in the source's order.
 */
export async function cloneProject(
  actor: Actor,
  input: CloneProjectInput,
): Promise<Project> {
  assertOrgScope(actor, input.orgId);

  const source = requireFound(
    await projectRepo.findProjectById(input.orgId, input.projectId),
    "Project",
    input.projectId,
  );
  assertCan(actor, "project:read", projectResource(source));
  assertCan(actor, "project:create", orgResource(input.orgId));
  assertNotArchived("Project", source.id, source);

  const org = requireFound(
    await orgRepo.findOrgById(input.orgId),
    "Organization",
    input.orgId,
  );

  const used = await projectRepo.countProjects(input.orgId);
  if (wouldExceedLimit(org.plan, "projects", used)) {
    throw new Error(
      `Plan ${org.plan} allows ${used} projects; upgrade to add another`,
    );
  }

  const sourceIssues: Issue[] = [];
  if (input.includeIssues) {
    let cursor: string | null = null;
    do {
      const page: Page<Issue> = await issueRepo.listIssues({
        orgId: input.orgId,
        projectId: source.id,
        limit: 100,
        cursor,
      });
      sourceIssues.push(...page.items.filter((issue) => !issue.archivedAt));
      cursor = page.nextCursor;
    } while (cursor);
    sourceIssues.sort((a, b) => a.number - b.number);

    if (
      sourceIssues.length > 0 &&
      wouldExceedLimit(org.plan, "issuesPerProject", 0, sourceIssues.length)
    ) {
      throw new Error(
        `Plan ${org.plan} allows no more than the issues already in a project; ${source.key} has ${sourceIssues.length}`,
      );
    }
  }

  const project = await projectRepo.insertProject({
    orgId: input.orgId,
    name: input.name,
    slug: input.slug,
    key: input.key,
    description: source.description,
    visibility: source.visibility,
    leadId: source.leadId,
    color: source.color,
    targetDate: null,
  });

  const status = defaultIssueStatus(org.settings.defaultIssueStatus);
  let number = 0;
  for (const issue of sourceIssues) {
    number += 1;
    await issueRepo.insertIssue(
      {
        orgId: input.orgId,
        projectId: project.id,
        title: issue.title,
        description: issue.description,
        status,
        priority: issue.priority,
        assigneeId: null,
        parentId: null,
        estimate: issue.estimate,
        dueAt: issue.dueAt,
        labelIds: [...issue.labelIds],
      },
      actor.userId,
      number,
    );
  }

  await emit("project.cloned", {
    ...actorEnvelope(actor),
    projectId: project.id,
    sourceProjectId: source.id,
    issuesCopied: sourceIssues.length,
  });

  return project;
}

function defaultIssueStatus(stored: string): IssueStatus {
  const parsed = issueStatusSchema.safeParse(stored);
  return parsed.success ? parsed.data : "backlog";
}
